package cn.zhuatech.lims.controller; import cn.zhuatech.lims.common.ApiResponse; import cn.zhuatech.lims.dto.LimsDto.*; import cn.zhuatech.lims.service.LimsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('TECHNICIAN','ADMIN')") public class TechnicianController {private final LimsService lims;public TechnicianController(LimsService lims){this.lims=lims;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(lims.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",lims.report(id,request));}}
